module fsm (
    input IN, 
    input CLK, 
    input RST, 
    output MATCH
);
// Internal signals
reg [2:0] ST_cr, ST_nt;
// State encoding
parameter [2:0] S0 = 3'b000;
parameter [2:0] S1 = 3'b001;
parameter [2:0] S2 = 3'b010;
parameter [2:0] S3 = 3'b011;
parameter [2:0] S4 = 3'b100;
parameter [2:0] S5 = 3'b101;
// Next state logic
always @(*) begin
    case(ST_cr)
        S0: ST_nt = (IN == 1'b1) ? S1 : S0;
        S1: ST_nt = (IN == 1'b0) ? S2 : S1;
        S2: ST_nt = (IN == 1'b0) ? S3 : S0;
        S3: ST_nt = (IN == 1'b1) ? S4 : S0;
        S4: ST_nt = (IN == 1'b1) ? S5 : S2;
        S5: ST_nt = (IN == 1'b0) ? S2 : S1;
        default: ST_nt = S0;
    endcase
end
// Current state update logic
always @(posedge CLK or posedge RST) begin
    if(RST) ST_cr <= S0;
    else ST_cr <= ST_nt;
end
// Combinational logic for MATCH
assign MATCH = (RST) ? 1'b0 :
               (ST_cr == S4 && IN == 1'b1) ? 1'b1 :
               1'b0;
endmodule
